class.description:
Rien de ce qui est affiché ne touche la vraie scène. Glisser (clic gauche) fait tourner la caméra autour du contenu, la molette zoome. Le contenu est libéré avec la scène. Le viewport n'est rendu que quand il est visible.
[codeblock]
func _build_preview(source: Variant) -> Control:
	var scene := make_stage_3d()
	var cube := MeshInstance3D.new()
	cube.mesh = BoxMesh.new()
	scene.set_content(cube)
	return scene
[/codeblock]
